"""Expanding-window walk-forward backtest for SES / Holt.

Protocol
--------
For each cutoff c in [start, n):
  * training data is strictly series[:c] (everything BEFORE the cutoff);
  * parameters are refitted at cutoffs that are multiples of `refit_every`
    (measured from `start`) and frozen in between;
  * a one-step forecast is made for series[c] and scored against the actual.

Every record logs the exact parameters used, so the refit schedule is
auditable.
"""
import numpy as np

import holt
import ses


def generate_series(n=300, seed=10, level0=200.0, drift=1.5, noise_sd=8.0):
    """Trending synthetic series: level + drift*t + N(0, noise_sd)."""
    rng = np.random.default_rng(seed)
    t = np.arange(n, dtype=float)
    return level0 + drift * t + rng.normal(0.0, noise_sd, n)


def fit_params(history, model="holt"):
    if model == "ses":
        return {"alpha": ses.fit_alpha(history)}
    if model == "holt":
        alpha, beta = holt.fit_holt(history)
        return {"alpha": alpha, "beta": beta}
    raise ValueError(f"unknown model: {model!r}")


def one_step_forecast(history, params, model="holt"):
    history = np.asarray(history, dtype=float)
    if model == "ses":
        return float(ses.ses_forecast(history, params["alpha"])[0])
    if model == "holt":
        return float(holt.holt_forecast(history, params["alpha"], params["beta"])[0])
    raise ValueError(f"unknown model: {model!r}")


def refit_point(cutoff, start=100, refit_every=25):
    """Most recent cutoff (>= start) at which a refit must have happened."""
    return start + ((cutoff - start) // refit_every) * refit_every


def walk_forward(series, start=100, refit_every=25, model="holt"):
    """Run the harness; returns one record per step with params logged."""
    series = np.asarray(series, dtype=float)
    records = []
    param_cache = {}  # refit point -> fitted params
    for cutoff in range(start, series.shape[0]):
        rp = refit_point(cutoff, start, refit_every)
        if rp not in param_cache:
            # Refits see ONLY data up to the refit point -- never the future.
            param_cache[rp] = fit_params(series[:rp], model=model)
        params = dict(param_cache[rp])  # log a copy per step
        forecast = one_step_forecast(series[:cutoff], params, model=model)
        records.append({
            "cutoff": cutoff,
            "refit_point": rp,
            "params": params,
            "forecast": forecast,
            "actual": float(series[cutoff]),
            "abs_error": abs(forecast - float(series[cutoff])),
        })
    return records


def mae(records):
    return float(np.mean([r["abs_error"] for r in records]))

